//! Go `ast.As<Kind>().<Field>` accessors and `ast.Is<Kind>` / `ast.Is<X>Kind`
//! helpers from pinned typescript-go `internal/ast/ast_generated.go`.
//!
//! Generated by a one-off script from `ast_generated.go` (Go struct fields and
//! `Is*` functions) and `crates/ts_ast/src/ast_generated.rs` (the `NodeData`
//! variants that hold the data). Regenerate instead of editing by hand.
//!
//! Rules (see PORTING.md "AST"):
//! - One `Node` method per exported Go node field. It works for every node
//!   struct that has the field and panics on other kinds, like a Go `AsX()`
//!   type assertion.
//! - Go fields that share a name with a Go `*Node` method (`Name`, `Body`,
//!   `Type`, `Expression`, `Text`, `Arguments`, ...) are not generated here.
//!   The `node.rs` method wins.
//! - Binder fields (`Symbol`, `LocalSymbol`, `Locals`, `NextContainer`,
//!   `FlowNode`, `EndFlowNode`, `ReturnFlowNode`) come from `NodeBindData`
//!   through `node.rs`. `SourceFile` fields other than `EndOfFileToken` come
//!   from `source_file_info` / `file_bind_data`.
//! - Unexported Go fields (`name`, `modifiers`, `facts`, `text`) are only
//!   reachable through Go `*Node` methods, so they are not generated.

use crate::prelude::*;
use ts_ast::NodeData;

/// The ts_ast data for `n`. Go reads node fields without a context; we reach
/// the parsed arena through the installed program.
fn node_data(n: Node) -> &'static NodeData {
    debug_assert!(n.is_some(), "nil node dereference");
    ast_data_of(n)
}

/// Go `nil` for an optional child.
fn opt_node(file: usize, id: Option<ts_ast::NodeId>) -> Node {
    match id {
        Some(id) => Node::new(file, id),
        None => Node::NIL,
    }
}

/// Builds the `NodeList` handle for a ts_ast list. `None` is Go `nil`.
// PORT: PORTING.md gives `NodeList` only as an example shape
// (`{ file: u32, list: Option<&'static ts_ast::NodeList> }`). This is the one
// place that depends on that shape.
fn make_node_list(file: usize, list: Option<&'static ts_ast::NodeList>) -> NodeList {
    NodeList { file: file as u32, list }
}

/// Go panics with a failed type assertion when `AsX()` gets the wrong kind.
#[cold]
fn field_panic(n: Node, field: &str) -> ! {
    panic!("ast field {field} does not exist on node kind {:?}", n.kind())
}

