    /// Go `node.AsX().FullSignature` for: FunctionDeclaration, CallSignatureDeclaration, ConstructSignatureDeclaration, ConstructorDeclaration, GetAccessorDeclaration, SetAccessorDeclaration, IndexSignatureDeclaration, MethodSignatureDeclaration, MethodDeclaration, ArrowFunction, FunctionExpression, FunctionTypeNode, ConstructorTypeNode, JSDocSignature.
    #[must_use]
    pub fn full_signature(self) -> Node {
        let file = self.file_index();
        match node_data(self) {
            NodeData::FunctionDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::CallSignatureDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::ConstructSignatureDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::ConstructorDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::GetAccessorDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::SetAccessorDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::IndexSignatureDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::MethodSignatureDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::MethodDeclaration(d) => opt_node(file, d.full_signature),
            NodeData::ArrowFunction(d) => opt_node(file, d.full_signature),
            NodeData::FunctionExpression(d) => opt_node(file, d.full_signature),
            NodeData::FunctionTypeNode(d) => opt_node(file, d.full_signature),
            NodeData::ConstructorTypeNode(d) => opt_node(file, d.full_signature),
            NodeData::JsDocSignature(d) => opt_node(file, d.full_signature),
            _ => field_panic(self, "FullSignature"),
        }
    }

